"""Data model. Plain dataclasses with to_dict/from_dict. No I/O here."""

from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any


class Severity(Enum):
    HIGH = "high"
    MEDIUM = "medium"
    LOW = "low"

    @property
    def rank(self) -> int:
        # Higher rank means more severe.
        return {"high": 3, "medium": 2, "low": 1}[self.value]

    def __lt__(self, other: Severity) -> bool:
        if not isinstance(other, Severity):
            return NotImplemented
        return self.rank < other.rank

    def __le__(self, other: Severity) -> bool:
        if not isinstance(other, Severity):
            return NotImplemented
        return self.rank <= other.rank

    def __gt__(self, other: Severity) -> bool:
        if not isinstance(other, Severity):
            return NotImplemented
        return self.rank > other.rank

    def __ge__(self, other: Severity) -> bool:
        if not isinstance(other, Severity):
            return NotImplemented
        return self.rank >= other.rank


@dataclass(frozen=True)
class Observation:
    """What really happened (truth) next to what the trace recorded (trace)."""

    truth: dict[str, Any]
    trace: dict[str, Any]

    def to_dict(self) -> dict[str, Any]:
        return {"truth": dict(self.truth), "trace": dict(self.trace)}

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> Observation:
        return cls(truth=dict(d["truth"]), trace=dict(d["trace"]))


@dataclass(frozen=True)
class Mismatch:
    """One field where truth and trace disagree."""

    field: str
    truth: Any
    trace: Any
    severity: Severity

    def to_dict(self) -> dict[str, Any]:
        return {
            "field": self.field,
            "truth": self.truth,
            "trace": self.trace,
            "severity": self.severity.value,
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> Mismatch:
        return cls(
            field=d["field"],
            truth=d["truth"],
            trace=d["trace"],
            severity=Severity(d["severity"]),
        )


@dataclass(frozen=True)
class Run:
    """One scenario run against the fake provider."""

    id: str
    scenario: str
    library: str
    observation: Observation
    mismatches: tuple[Mismatch, ...] = ()

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "scenario": self.scenario,
            "library": self.library,
            "observation": self.observation.to_dict(),
            "mismatches": [m.to_dict() for m in self.mismatches],
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> Run:
        return cls(
            id=d["id"],
            scenario=d["scenario"],
            library=d["library"],
            observation=Observation.from_dict(d["observation"]),
            mismatches=tuple(Mismatch.from_dict(m) for m in d.get("mismatches", [])),
        )


@dataclass(frozen=True)
class Finding:
    """A confirmed, deduplicated problem in a tracing library."""

    id: str
    title: str
    library: str
    severity: Severity
    run_ids: tuple[str, ...] = ()
    cause: str | None = None
    details: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "title": self.title,
            "library": self.library,
            "severity": self.severity.value,
            "run_ids": list(self.run_ids),
            "cause": self.cause,
            "details": dict(self.details),
        }

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> Finding:
        return cls(
            id=d["id"],
            title=d["title"],
            library=d["library"],
            severity=Severity(d["severity"]),
            run_ids=tuple(d.get("run_ids", [])),
            cause=d.get("cause"),
            details=dict(d.get("details", {})),
        )
"""Pure core: data model and logic with no I/O."""

from trueup.core.model import Finding, Mismatch, Observation, Run, Severity

__all__ = ["Finding", "Mismatch", "Observation", "Run", "Severity"]
"""Command line entry point."""

from __future__ import annotations

import argparse
import os
import sys
from pathlib import Path
from typing import Sequence

from trueup.runner.setups import LIBRARIES

# Exit codes
EXIT_OK = 0  # no mismatches
EXIT_MISMATCH = 1  # mismatches found
EXIT_ERROR = 2  # could not run

KEY_VARS = ("NEATLOGS_API_KEY", "TRUEUP_MODEL_KEY")
NOT_BUILT = ("audit", "fix", "upstream", "verify", "report")


def doctor() -> int:
    ok = sys.version_info >= (3, 12)
    v = sys.version_info
    print(f"python: {v.major}.{v.minor}.{v.micro} ({'ok' if ok else 'need 3.12+'})")
    for name in KEY_VARS:
        # Only report presence. Never print the value.
        state = "set" if os.environ.get(name) else "not set"
        print(f"{name}: {state}")
    return EXIT_OK if ok else EXIT_ERROR


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="trueup",
        description="Find where AI agent traces disagree with what really happened.",
    )
    sub = parser.add_subparsers(dest="command", required=True)
    for name in NOT_BUILT:
        sub.add_parser(name, help="not built yet")
    sub.add_parser("doctor", help="check the local setup")
    sw = sub.add_parser("sweep", help="run the plain-SDK scenarios against one tracing library")
    sw.add_argument("library", choices=LIBRARIES)
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = build_parser().parse_args(argv)
    if args.command == "doctor":
        return doctor()
    if args.command == "sweep":
        from trueup.sweep import exit_code, sweep

        _, results = sweep(Path.cwd(), args.library)
        return exit_code(results)
    print(f"trueup {args.command}: not built yet", file=sys.stderr)
    return EXIT_ERROR


if __name__ == "__main__":
    sys.exit(main())
"""trueup sweep <library>: run the plain-SDK scenarios against one library."""

from __future__ import annotations

import json
import time
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable

from trueup.runner import NOT_RUN, RAN, run_scenario, venvs
from trueup.runner.run import not_run
from trueup.scenarios import plain_sdk


def new_run_id(library: str) -> str:
    return datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + f"-{library}"


def summary_line(r: dict[str, Any]) -> str:
    sid = r["scenario"]
    if r["status"] != RAN:
        return f"{sid:30} NOT RUN  {r['reason']}"
    t, tr = r["observation"]["truth"], r["observation"]["trace"]
    app = t["app"]["outcome"] if t["outcome"] == "ok" else f"raised {t['exception']}"
    spans = ", ".join(f"{s['name']}={s['status']['code']}" for s in tr["spans"]) or "none"
    line = f"{sid:30} ran {r['seconds']:5.1f}s  app {app}; fake calls {t['calls']}; spans {len(tr['spans'])}: {spans}"
    if t["expected_mismatch"]:
        line += f"  [truth differs from scenario expectation: {', '.join(t['expected_mismatch'])}]"
    return line


def sweep(
    root: Path,
    library: str,
    *,
    ensure: Callable[[Path, str], Path] = venvs.ensure,
    run: Callable[..., dict[str, Any]] = run_scenario,
    out: Callable[[str], None] = print,
) -> tuple[Path, list[dict[str, Any]]]:
    run_id = new_run_id(library)
    run_dir = root / ".trueup" / "runs" / run_id
    run_dir.mkdir(parents=True, exist_ok=True)
    started = time.monotonic()
    scenarios = plain_sdk()
    try:
        out(f"preparing venv for {library}")
        python: Path | None = ensure(root, library)
        venv_error = None
    except Exception as e:  # noqa: BLE001 - every scenario is reported NOT RUN
        python, venv_error = None, f"venv not ready: {e}"
    results = []
    for s in scenarios:
        r = not_run(s.id, library, venv_error) if python is None else run(python, library, s.id)
        results.append(r)
        out(summary_line(r))
        (run_dir / f"{s.id}.json").write_text(json.dumps(r, indent=1, default=str))
    ran = sum(r["status"] == RAN for r in results)
    lines = [
        f"trueup sweep {library}  run {run_id}",
        f"scenarios: {len(results)}  ran: {ran}  not run: {len(results) - ran}  "
        f"time: {time.monotonic() - started:.0f} s",
        "Truth and trace are recorded here; comparing them is not built yet.",
        "",
        *(summary_line(r) for r in results),
    ]
    (run_dir / "summary.txt").write_text("\n".join(lines) + "\n")
    (run_dir / "index.json").write_text(json.dumps({
        "run_id": run_id,
        "library": library,
        "scenarios": [{"id": r["scenario"], "status": r["status"], "reason": r["reason"]} for r in results],
    }, indent=1))
    out(f"ran {ran}/{len(results)}; wrote {run_dir}")
    return run_dir, results


def exit_code(results: list[dict[str, Any]]) -> int:
    # 2 (could not run) if anything was NOT RUN; mismatches are not judged yet.
    return 2 if any(r["status"] == NOT_RUN for r in results) else 0
"""Parent side: run one scenario in a fresh subprocess and read its observation."""

from __future__ import annotations

import json
import os
import subprocess
import tempfile
import time
from pathlib import Path
from typing import Any

from trueup.runner.setups import CHILD_ENV, CHILD_ENV_DROP
from trueup.scenarios import BUILT, get

SRC = Path(__file__).resolve().parents[2]  # .../src
RAN = "ran"
NOT_RUN = "not_run"


def child_env(base: dict[str, str] | None = None) -> dict[str, str]:
    env = dict(os.environ if base is None else base)
    for k in CHILD_ENV_DROP:
        env.pop(k, None)
    env.update(CHILD_ENV)
    env["PYTHONPATH"] = str(SRC)
    env.pop("VIRTUAL_ENV", None)
    return env


def not_run(scenario_id: str, library: str, reason: str, seconds: float = 0.0, detail: str | None = None) -> dict[str, Any]:
    return {"scenario": scenario_id, "library": library, "status": NOT_RUN, "reason": reason,
            "detail": detail, "seconds": round(seconds, 3), "observation": None}


def _last_line(text: str) -> str:
    lines = [ln for ln in text.strip().splitlines() if ln.strip()]
    return lines[-1].strip() if lines else "no output"


def run_scenario(python: Path, library: str, scenario_id: str, timeout: float = 90) -> dict[str, Any]:
    """Returns {scenario, library, status, reason, seconds, observation}."""
    try:
        scenario = get(scenario_id)
    except KeyError as e:
        return not_run(scenario_id, library, str(e))
    if scenario.status != BUILT:
        return not_run(scenario_id, library, f"scenario is {scenario.status}")
    with tempfile.TemporaryDirectory(prefix="trueup-") as tmp:
        out = Path(tmp) / "obs.json"
        cmd = [str(python), "-m", "trueup.runner.child", library, scenario_id, str(out)]
        t0 = time.monotonic()
        try:
            p = subprocess.run(cmd, env=child_env(), cwd=tmp, capture_output=True, text=True, timeout=timeout)
        except subprocess.TimeoutExpired:
            return not_run(scenario_id, library, f"timed out after {timeout:.0f} s", time.monotonic() - t0)
        except OSError as e:
            return not_run(scenario_id, library, f"could not start {python}: {e}")
        seconds = time.monotonic() - t0
        if not out.exists():
            tail = (p.stderr or p.stdout).strip()[-2000:]
            return not_run(scenario_id, library, f"child exited {p.returncode} without output: {_last_line(tail)}",
                           seconds, detail=tail)
        payload = json.loads(out.read_text())
    if not payload["ok"]:
        return not_run(scenario_id, library, "setup or harness error: " + _last_line(payload["error"]), seconds,
                       detail=payload["error"])
    return {"scenario": scenario_id, "library": library, "status": RAN, "reason": None,
            "seconds": round(seconds, 3), "observation": payload["observation"]}
"""Turn the fake's log and the app outcome into truth fields. Pure functions."""

from __future__ import annotations

from typing import Any


def derive(fake_log: list[dict[str, Any]], app: dict[str, Any]) -> dict[str, Any]:
    """Truth in the same shape as a scenario's `expected`."""
    out: dict[str, Any] = {
        "calls": len(fake_log),
        "outcome": app["outcome"],
        "tokens": [
            None if e["usage"] is None else {"input": e["usage"]["input_tokens"], "output": e["usage"]["output_tokens"]}
            for e in fake_log
        ],
        "finish": [e["finish"] for e in fake_log],
        "tool_calls": [[t["name"] for t in e["tool_calls"]] for e in fake_log],
        "fake": [e["outcome"] for e in fake_log],
        "response_ids": [e["response_id"] for e in fake_log],
    }
    if app["outcome"] == "exception":
        out["exception"] = app["exception_type"]
    return out


def check_expected(expected: dict[str, Any], truth: dict[str, Any]) -> list[str]:
    """Keys where the run's truth differs from what the scenario expects."""
    return [k for k, v in expected.items() if truth.get(k) != v]

"""App code for each scenario: plain SDK calls, the way an app would write them.

Each function takes the fake's base URL and the scenario's model name and
returns what the app saw. Exceptions are left to propagate; the runner records
them as the app outcome.

Every function builds its own client. Reusing one async client across two
asyncio.run() loops fails with "Event loop is closed" on the second loop, which
would show up as a false app error.
"""

from __future__ import annotations

import asyncio
from typing import Any, Callable

M = [{"role": "user", "content": "What is the weather in Lagos?"}]
OA_TOOLS = [
    {"type": "function", "function": {"name": "get_weather", "parameters": {"type": "object", "properties": {"city": {"type": "string"}}}}},
    {"type": "function", "function": {"name": "get_time", "parameters": {"type": "object", "properties": {"tz": {"type": "string"}}}}},
]
RESP_TOOLS = [{"type": "function", "name": "get_weather", "parameters": {"type": "object", "properties": {"city": {"type": "string"}}}}]
AN_TOOLS = [{"name": "get_weather", "input_schema": {"type": "object", "properties": {"city": {"type": "string"}}}}]


def _oa(base: str):
    import openai

    return openai.OpenAI(api_key="trueup-fake", base_url=f"{base}/v1", max_retries=0)


def _an(base: str):
    import anthropic

    return anthropic.Anthropic(api_key="trueup-fake", base_url=base, max_retries=0)


# OpenAI Chat Completions


def chat_create(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        r = c.chat.completions.create(model=model, messages=M)
    m = r.choices[0].message
    return {"text": m.content, "refusal": m.refusal, "finish": r.choices[0].finish_reason, "total_tokens": r.usage.total_tokens}


def chat_create_tools(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        r = c.chat.completions.create(model=model, messages=M, tools=OA_TOOLS)
    calls = r.choices[0].message.tool_calls or []
    return {"tool_calls": [{"name": t.function.name, "arguments": t.function.arguments} for t in calls]}


def chat_create_n2(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        r = c.chat.completions.create(model=model, messages=M, n=2)
    return {"choices": [ch.message.content for ch in r.choices]}


def _read_chat_stream(stream) -> dict[str, Any]:
    out: dict[str, Any] = {"text": "", "tool_calls": {}, "finish": None, "total_tokens": None}
    for ch in stream:
        if ch.usage:
            out["total_tokens"] = ch.usage.total_tokens
        for c in ch.choices:
            out["text"] += c.delta.content or ""
            out["finish"] = c.finish_reason or out["finish"]
            for tc in c.delta.tool_calls or []:
                d = out["tool_calls"].setdefault(str(tc.index), {"name": "", "arguments": ""})
                d["name"] += tc.function.name or ""
                d["arguments"] += tc.function.arguments or ""
    out["tool_calls"] = list(out["tool_calls"].values())
    return out


def chat_stream(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        return _read_chat_stream(c.chat.completions.create(model=model, messages=M, stream=True))


def chat_stream_usage(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        return _read_chat_stream(
            c.chat.completions.create(model=model, messages=M, stream=True, stream_options={"include_usage": True})
        )


def chat_stream_tools(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        return _read_chat_stream(c.chat.completions.create(model=model, messages=M, tools=OA_TOOLS, stream=True))


def chat_stream_break(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        s = c.chat.completions.create(model=model, messages=M, stream=True)
        chunks = 0
        for _ in s:
            chunks += 1
            break
        s.close()
    return {"chunks_read": chunks}


def chat_async_stream(base: str, model: str) -> dict[str, Any]:
    import openai

    async def go() -> dict[str, Any]:
        text, tokens = "", None
        async with openai.AsyncOpenAI(api_key="trueup-fake", base_url=f"{base}/v1", max_retries=0) as c:
            stream = await c.chat.completions.create(
                model=model, messages=M, stream=True, stream_options={"include_usage": True}
            )
            async for ch in stream:
                if ch.usage:
                    tokens = ch.usage.total_tokens
                for x in ch.choices:
                    text += x.delta.content or ""
        return {"text": text, "total_tokens": tokens}

    return asyncio.run(go())


# OpenAI Responses


def resp_create(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        r = c.responses.create(model=model, input="What is the weather in Lagos?", tools=RESP_TOOLS)
    return {
        "status": r.status,
        "output_types": [o.type for o in r.output],
        "text": r.output_text,
        "total_tokens": r.usage.total_tokens if r.usage else None,
    }


def resp_stream(base: str, model: str) -> dict[str, Any]:
    with _oa(base) as c:
        with c.responses.stream(model=model, input="What is the weather in Lagos?", tools=RESP_TOOLS) as s:
            for _ in s:
                pass
            r = s.get_final_response()
    return {"status": r.status, "output_types": [o.type for o in r.output], "text": r.output_text}


def resp_stream_raw(base: str, model: str) -> dict[str, Any]:
    # The SDK yields a Responses `error` event instead of raising; an app
    # that checks for it raises its own error, which is what we do here.
    with _oa(base) as c:
        types = []
        for ev in c.responses.create(model=model, input="hi", stream=True):
            types.append(ev.type)
            if ev.type == "error":
                raise RuntimeError(f"stream error event: {ev.message}")
    return {"events": types}


# Anthropic Messages


def an_create(base: str, model: str) -> dict[str, Any]:
    with _an(base) as c:
        r = c.messages.create(model=model, max_tokens=64, messages=M)
    return {"blocks": [b.type for b in r.content], "stop_reason": r.stop_reason}


def an_stream_helper(base: str, model: str, **kw: Any) -> dict[str, Any]:
    with _an(base) as c:
        with c.messages.stream(model=model, max_tokens=64, messages=M, **kw) as s:
            text = "".join(s.text_stream)
            fm = s.get_final_message()
    return {
        "text": text,
        "blocks": [b.type for b in fm.content],
        "tool_inputs": [b.input for b in fm.content if b.type == "tool_use"],
        "usage": [fm.usage.input_tokens, fm.usage.output_tokens],
    }


def an_stream_helper_tools(base: str, model: str) -> dict[str, Any]:
    return an_stream_helper(base, model, tools=AN_TOOLS)


def an_create_stream(base: str, model: str) -> dict[str, Any]:
    with _an(base) as c:
        text = ""
        for ev in c.messages.create(model=model, max_tokens=64, messages=M, stream=True):
            if ev.type == "content_block_delta" and ev.delta.type == "text_delta":
                text += ev.delta.text
    return {"text": text}


def an_async_create(base: str, model: str) -> dict[str, Any]:
    import anthropic

    async def go() -> dict[str, Any]:
        async with anthropic.AsyncAnthropic(api_key="trueup-fake", base_url=base, max_retries=0) as c:
            r = await c.messages.create(model=model, max_tokens=64, messages=M)
        return {"text": r.content[0].text}

    return asyncio.run(go())


APPS: dict[str, Callable[[str, str], dict[str, Any]]] = {
    name: fn
    for name, fn in dict(globals()).items()
    if callable(fn) and not name.startswith("_") and getattr(fn, "__module__", None) == __name__
}
"""What the fake sends back for one request, plus the facts the truth log keeps."""

from __future__ import annotations

import itertools
import json
import secrets
import threading
from dataclasses import dataclass, field
from typing import Any


@dataclass
class Reply:
    status: int
    body: bytes
    content_type: str = "application/json"
    # Write the body, then drop the connection before the declared length.
    cut: bool = False
    # Truth facts about this reply.
    response_id: str | None = None
    outcome: str = "complete"  # complete, failed, incomplete, error_event, cut, http_error
    usage: dict[str, int] | None = None  # None means the fake sent no usage
    finish: list[str | None] = field(default_factory=list)
    tool_calls: list[dict[str, Any]] = field(default_factory=list)
    text: list[str] = field(default_factory=list)
    headers: dict[str, str] = field(default_factory=dict)

    def facts(self) -> dict[str, Any]:
        return {
            "status_code": self.status,
            "response_id": self.response_id,
            "outcome": self.outcome,
            "usage": dict(self.usage) if self.usage is not None else None,
            "usage_sent": self.usage is not None,
            "finish": list(self.finish),
            "tool_calls": [dict(t) for t in self.tool_calls],
            "text": list(self.text),
        }


class Ids:
    """Ids unique per call and per server instance.

    Reusing a response id across calls makes some libraries treat the second
    span as a duplicate and drop it, so every id carries a per-server token and
    a counter.
    """

    def __init__(self) -> None:
        self._token = secrets.token_hex(4)
        self._count = itertools.count(1)
        self._lock = threading.Lock()

    def new(self, prefix: str) -> str:
        with self._lock:
            n = next(self._count)
        return f"{prefix}{self._token}{n:04d}"


def dumps(obj: Any) -> bytes:
    return json.dumps(obj, separators=(",", ":")).encode()


def json_reply(status: int, obj: Any, **kw: Any) -> Reply:
    return Reply(status=status, body=dumps(obj), **kw)


def sse(data: Any, event: str | None = None) -> bytes:
    head = f"event: {event}\n" if event else ""
    payload = data if isinstance(data, str) else json.dumps(data, separators=(",", ":"))
    return f"{head}data: {payload}\n\n".encode()


def stream_reply(parts: list[bytes], **kw: Any) -> Reply:
    return Reply(status=200, body=b"".join(parts), content_type="text/event-stream", **kw)
"""Local HTTP fake provider. Runs in a thread on a random free port."""

from __future__ import annotations

import json
import socket
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Callable

from trueup.fake import anthropic_messages, openai_chat, openai_responses
from trueup.fake.reply import Ids, Reply, json_reply

ROUTES: dict[str, tuple[str, Callable[[str, dict[str, Any], Ids], Reply]]] = {
    "/v1/chat/completions": ("openai.chat", openai_chat.handle),
    "/v1/responses": ("openai.responses", openai_responses.handle),
    "/v1/messages": ("anthropic.messages", anthropic_messages.handle),
}
SCENARIOS = openai_chat.SCENARIOS + openai_responses.SCENARIOS + anthropic_messages.SCENARIOS


class TruthLog:
    """Every request the fake got and what it sent back. Thread-safe."""

    def __init__(self) -> None:
        self._entries: list[dict[str, Any]] = []
        self._lock = threading.Lock()

    def add(self, entry: dict[str, Any]) -> None:
        with self._lock:
            entry["seq"] = len(self._entries) + 1
            self._entries.append(entry)

    def entries(self) -> list[dict[str, Any]]:
        with self._lock:
            return json.loads(json.dumps(self._entries))

    def clear(self) -> None:
        with self._lock:
            self._entries.clear()

    def summary(self) -> dict[str, Any]:
        entries = self.entries()
        return {
            "calls": len(entries),
            "tokens_per_call": [e["usage"] for e in entries],
            "response_ids": [e["response_id"] for e in entries],
        }


class _Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server: _Server

    def log_message(self, *args: Any) -> None:
        pass

    def do_POST(self) -> None:
        raw = self.rfile.read(int(self.headers.get("Content-Length") or 0))
        path = self.path.split("?", 1)[0]
        try:
            req = json.loads(raw or b"{}")
        except ValueError:
            req = {}
        api, handler = ROUTES.get(path, ("unknown", None))
        scenario = str(req.get("model", ""))
        if handler is None:
            reply = json_reply(404, {"error": {"message": f"no route {path}", "type": "not_found"}}, outcome="http_error")
        else:
            reply = handler(scenario, req, self.server.ids)
        self.server.log.add({
            "api": api,
            "path": path,
            "scenario": scenario,
            "stream": bool(req.get("stream")),
            "include_usage": bool((req.get("stream_options") or {}).get("include_usage")),
            "n": req.get("n"),
            **reply.facts(),
        })
        self._send(reply)

    def _send(self, reply: Reply) -> None:
        self.send_response(reply.status)
        self.send_header("Content-Type", reply.content_type)
        for k, v in reply.headers.items():
            self.send_header(k, v)
        if reply.cut:
            # Promise more bytes than we send, then drop the connection.
            self.send_header("Content-Length", str(len(reply.body) + 512))
            self.end_headers()
            self.wfile.write(reply.body)
            self.wfile.flush()
            try:
                self.connection.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
            self.close_connection = True
            return
        self.send_header("Content-Length", str(len(reply.body)))
        self.end_headers()
        self.wfile.write(reply.body)


class _Server(ThreadingHTTPServer):
    daemon_threads = True
    log: TruthLog
    ids: Ids


class FakeProvider:
    """Use as a context manager, or call start() and stop()."""

    def __init__(self) -> None:
        self.log = TruthLog()
        self._server: _Server | None = None
        self._thread: threading.Thread | None = None

    def start(self) -> FakeProvider:
        server = _Server(("127.0.0.1", 0), _Handler)
        server.log = self.log
        server.ids = Ids()
        self._server = server
        self._thread = threading.Thread(target=server.serve_forever, kwargs={"poll_interval": 0.05}, name="trueup-fake", daemon=True)
        self._thread.start()
        return self

    def stop(self) -> None:
        if self._server is not None:
            self._server.shutdown()
            self._server.server_close()
            self._server = None

    def __enter__(self) -> FakeProvider:
        return self.start()

    def __exit__(self, *exc: Any) -> None:
        self.stop()

    @property
    def port(self) -> int:
        assert self._server is not None, "fake not started"
        return self._server.server_address[1]

    @property
    def base_url(self) -> str:
        """Anthropic base_url (the SDK adds /v1)."""
        return f"http://127.0.0.1:{self.port}"

    @property
    def openai_base_url(self) -> str:
        return f"{self.base_url}/v1"
"""The scenario library, as data.

Each scenario names the fake model it calls (the fake picks its behaviour from
the model name), the app code that drives it (`app`, a function in
trueup.runner.apps), and the truth fields we expect the run to produce.

Expected truth keys (only the ones listed are checked):
  calls       number of requests the fake received
  outcome     "ok" or "exception" (what the app saw)
  exception   exception class name, when outcome is "exception"
  tokens      per call: {"input": n, "output": n}, or None when the fake sent no usage
  finish      per call: finish/stop reason or response status
  tool_calls  per call: tool names the model asked for
  fake        per call: what the fake did (complete, failed, incomplete, error_event, cut, http_error)
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

BUILT = "built"
NOT_BUILT = "not_built"

OA_TOK = {"input": 11, "output": 7}
AN_TOK = {"input": 5, "output": 3}


@dataclass(frozen=True)
class Scenario:
    id: str
    provider: str  # openai, anthropic
    api: str  # chat, responses, messages
    framework: str  # none, langchain, langgraph, openai-agents
    does: str  # what the app does, in plain words
    app: str  # function name in trueup.runner.apps
    model: str  # fake scenario, sent as the model name
    expected: dict[str, Any] = field(default_factory=dict)
    status: str = BUILT

    @property
    def plain_sdk(self) -> bool:
        return self.framework == "none"

    def to_dict(self) -> dict[str, Any]:
        return {
            "id": self.id,
            "provider": self.provider,
            "api": self.api,
            "framework": self.framework,
            "does": self.does,
            "app": self.app,
            "model": self.model,
            "expected": self.expected,
            "status": self.status,
        }


def _ok(tokens: Any, finish: Any, tools: Any = None, calls: int = 1, fake: str = "complete") -> dict[str, Any]:
    return {
        "calls": calls,
        "outcome": "ok",
        "tokens": [tokens] * calls,
        "finish": [finish] * calls,
        "tool_calls": [tools or []] * calls,
        "fake": [fake] * calls,
    }


def _raises(exc: str, fake: str) -> dict[str, Any]:
    return {"calls": 1, "outcome": "exception", "exception": exc, "tokens": [None], "fake": [fake]}


def _s(id: str, provider: str, api: str, does: str, app: str, model: str, expected: dict[str, Any]) -> Scenario:
    return Scenario(id, provider, api, "none", does, app, model, expected)


